import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { readMigrationFiles } from 'drizzle-orm/migrator';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { REPO_ROOT } from '../lib/config.js';
import type { DbHandle } from './client.js';

/** Versioned SQL migrations generated by drizzle-kit (`pnpm db:generate`). Forward-only. */
export const MIGRATIONS_DIR = path.join(REPO_ROOT, 'apps/api/migrations');
const MIGRATIONS_TABLE = '__drizzle_migrations';

export class MigrationDriftError extends Error {}

export interface MigrationStatus {
  available: number;
  applied: number;
  pending: string[];
}

interface FileMigration {
  tag: string;
  when: number;
  hash: string;
}

function readFiles(dir: string): FileMigration[] {
  const journalFile = path.join(dir, 'meta/_journal.json');
  if (!existsSync(journalFile)) return [];
  const journal = JSON.parse(readFileSync(journalFile, 'utf8')) as {
    entries: { tag: string; when: number }[];
  };
  // Same order as the journal; hashes computed exactly as drizzle stores them.
  const files = readMigrationFiles({ migrationsFolder: dir });
  return journal.entries.map((e, i) => ({ tag: e.tag, when: e.when, hash: files[i]!.hash }));
}

function readApplied(handle: DbHandle): { hash: string; when: number }[] {
  const hasTable = handle.sqlite
    .prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?")
    .get(MIGRATIONS_TABLE);
  if (!hasTable) return [];
  return (
    handle.sqlite
      .prepare(`SELECT hash, created_at AS "when" FROM ${MIGRATIONS_TABLE} ORDER BY created_at`)
      .all() as { hash: string; when: number | string }[]
  ).map((r) => ({ hash: r.hash, when: Number(r.when) }));
}

/**
 * Pending = newer than the last applied migration (drizzle's own rule).
 * Drizzle never notices drift, so this also verifies that every migration up to the last applied
 * one was applied with an identical SQL hash. Drift throws: an older migration merged after a
 * newer one (it would be silently skipped), an edited applied migration, or a DB from a newer
 * codebase.
 */
export function getMigrationStatus(handle: DbHandle, dir = MIGRATIONS_DIR): MigrationStatus {
  const files = readFiles(dir);
  const applied = readApplied(handle);
  const lastWhen = applied.at(-1)?.when ?? -1;
  const covered = files.filter((f) => f.when <= lastWhen);

  if (applied.length !== covered.length) {
    throw new MigrationDriftError(
      `Migration drift: database has ${applied.length} applied migration(s) but the code has ` +
        `${covered.length} up to that point. A migration was skipped/reordered, or the database ` +
        'is from a different codebase version. Do not run the app against it; investigate first.',
    );
  }
  covered.forEach((f, i) => {
    const a = applied[i]!;
    if (a.when !== f.when || a.hash !== f.hash) {
      throw new MigrationDriftError(
        `Migration drift: applied migration ${f.tag} differs from the file in the repo ` +
          '(edited after it was applied?). Applied migrations must never change.',
      );
    }
  });

  return {
    available: files.length,
    applied: applied.length,
    pending: files.filter((f) => f.when > lastWhen).map((f) => f.tag),
  };
}

/**
 * Applies pending migrations in ONE transaction (drizzle's sync migrator: BEGIN … COMMIT,
 * ROLLBACK on any error). Safe to run repeatedly. Refuses to run on drift.
 *
 * Caveats (see docs/operations.md → Schema changes):
 *  - `PRAGMA foreign_keys=OFF` inside a migration is a no-op (it runs inside the transaction),
 *    so table-rebuild migrations run with FKs ON. Fine while no FK cascades (ADR-008).
 *  - The final foreign_key_check runs AFTER commit: it detects, it cannot roll back.
 */
export function runMigrations(handle: DbHandle, dir = MIGRATIONS_DIR): MigrationStatus {
  const before = getMigrationStatus(handle, dir);
  if (before.available === 0 || before.pending.length === 0) return before;
  migrate(handle.db, { migrationsFolder: dir, migrationsTable: MIGRATIONS_TABLE });
  const fk = handle.sqlite.pragma('foreign_key_check') as unknown[];
  if (fk.length > 0) {
    throw new Error(
      `foreign_key_check reported ${fk.length} violation(s) after migration — restore the pre-migrate backup`,
    );
  }
  return getMigrationStatus(handle, dir);
}
